from math import gcd
class Solution:
    def maxGcdScore(self, nums: List[int], k: int) -> int:
        n = len(nums)
        cands = {gcd(nums[i], 2 * nums[j]) for i in range(n) for j in range(n)}
        ans = 0
        for g in cands:
            need = l = 0
            for r, x in enumerate(nums):
                if 2 * x % g:
                    need += 1
                while need > k:
                    if 2 * nums[l] % g:
                        need -= 1
                    l += 1
                ans = max(ans, (r - l + 1) * g)
        return ans

