public:
    long long maxGcdScore(vector<int>& nums, int k) {
        int n = nums.size();
        unordered_set<long long> cands;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                cands.insert(__gcd((long long)nums[i], 2LL * nums[j]));
        long long ans = 0;
        for (long long g : cands) {
            int need = 0, l = 0;
            for (int r = 0; r < n; r++) {
                if (2LL * nums[r] % g) need++;
                while (need > k) { if (2LL * nums[l] % g) need--; l++; }
                ans = max(ans, (long long)(r - l + 1) * g);
            }
        }
        return ans;
    }
};

