class Solution {
    private long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }
    public long maxGcdScore(int[] nums, int k) {
        int n = nums.length;
        Set<Long> cands = new HashSet<>();
        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                cands.add(gcd(nums[i], 2L * nums[j]));
        long ans = 0;
        for (long g : cands) {
            int need = 0, l = 0;
            for (int r = 0; r < n; r++) {
                if (2L * nums[r] % g != 0) need++;
                while (need > k) { if (2L * nums[l] % g != 0) need--; l++; }
                ans = Math.max(ans, (long)(r - l + 1) * g);
            }
        }
        return ans;
    }
}

