class Solution {
public:
    long long maxGcdScore(vector<int>& nums, int k) {
        long long ans = 0;
        int n = nums.size();
        for (int l = 0; l < n; l++) {
            unordered_map<long long,int> states;
            for (int r = l; r < n; r++) {
                long long x = nums[r];
                unordered_map<long long,int> ns;
                auto add = [&](long long g, int c) {
                    if (c <= k && (!ns.count(g) || c < ns[g])) ns[g] = c;
                };
                for (auto& [g, c] : states) { add(__gcd(g, x), c); add(__gcd(g, 2 * x), c + 1); }
                add(x, 0); add(2 * x, 1);
                states = move(ns);
                for (auto& [g, c] : states) ans = max(ans, (long long)(r - l + 1) * g);
            }
        }
        return ans;
    }
};

