class Solution {
    private long gcd(long a, long b) { return b == 0 ? a : gcd(b, a % b); }
    public long maxGcdScore(int[] nums, int k) {
        long ans = 0;
        int n = nums.length;
        for (int l = 0; l < n; l++) {
            Map<Long,Integer> states = new HashMap<>();
            for (int r = l; r < n; r++) {
                long x = nums[r];
                Map<Long,Integer> ns = new HashMap<>();
                for (Map.Entry<Long,Integer> e : states.entrySet()) {
                    long g = e.getKey(); int c = e.getValue();
                    ns.merge(gcd(g, x), c, Math::min);
                    if (c + 1 <= k) ns.merge(gcd(g, 2 * x), c + 1, Math::min);
                }
                ns.merge(x, 0, Math::min);
                ns.merge(2 * x, 1, Math::min);
                states = ns;
                for (long g : states.keySet()) ans = Math.max(ans, (long)(r - l + 1) * g);
            }
        }
        return ans;
    }
}

